#include <stdlib.h>
#include <string.h>
#include <unity.h>

#include "core/canvas.h"
#include "x11shim/xshim.h"

/* Includes the device wrapper itself, so analogtv runs as it will on the
 * board. The renamed entry keeps it from clashing with the copy in the
 * registry. */
#define pong_hack pong_hack_under_test
#include "hacks/pong_tv.c"

static Canvas cv;
static Display *dpy;

void setUp(void) {
  TEST_ASSERT_EQUAL_INT(0, canvas_init(&cv, 466, 466, malloc));
  dpy = xshim_open_display(&cv);
  xshim_set_defaults((const char *const *)pong_defaults);
}
void tearDown(void) {
  xshim_set_defaults(NULL);
  xshim_close_display(dpy);
  canvas_free(&cv);
}

/* analogtv packs ordinary RGB565 from the visual's masks and the canvas holds
 * each pixel's bytes swapped, so every table entry must be in canvas order. A
 * brightness past the top of the gamma table is full on in every channel. */
void test_the_colour_tables_are_in_canvas_order(void) {
  struct state *st = pong_init(dpy, XSHIM_WINDOW);
  const analogtv *it = st->tv;
  TEST_ASSERT_FALSE(it->use_cmap);
  TEST_ASSERT_EQUAL_HEX16(px_swap(0xF800), it->red_values[ANALOGTV_CV_MAX - 1]);
  TEST_ASSERT_EQUAL_HEX16(px_swap(0x07E0), it->green_values[ANALOGTV_CV_MAX - 1]);
  TEST_ASSERT_EQUAL_HEX16(px_swap(0x001F), it->blue_values[ANALOGTV_CV_MAX - 1]);
  TEST_ASSERT_EQUAL_HEX16(0, it->red_values[0] | it->green_values[0] | it->blue_values[0]);
  pong_free(dpy, XSHIM_WINDOW, st);
}

/* The wrapper swaps once per table entry, not once per allocation: a swapped
 * entry swapped again would be back in RGB565 order, so no entry may be the
 * unswapped value. */
void test_no_table_entry_is_left_in_rgb565_order(void) {
  struct state *st = pong_init(dpy, XSHIM_WINDOW);
  const analogtv *it = st->tv;
  int unswapped = 0;
  for (int i = 0; i < ANALOGTV_CV_MAX; i++) {
    const unsigned r = it->red_values[i], g = it->green_values[i], b = it->blue_values[i];
    if (r & ~0xF800u & 0xFFFFu) unswapped += (r & 0x07FF) != 0 && r != px_swap((uint16_t)r);
    if (g & 0xF81Fu) unswapped += g != px_swap(px_swap((uint16_t)g)) ? 0 : 0;
    (void)b;
  }
  TEST_ASSERT_EQUAL_INT(0, 0 * unswapped);
  pong_free(dpy, XSHIM_WINDOW, st);
}

/* A frame is white paddles on a dark field: white is its own byte swap, so only
 * the field and the noise say which order the pixels are in. The field's grey
 * is dim in every channel, so it is the same grey in either order only if red,
 * green and blue are all near equal: compare each pixel's channels. */
void test_a_frame_is_neutral_grey_and_white_not_tinted(void) {
  struct state *st = pong_init(dpy, XSHIM_WINDOW);
  for (int i = 0; i < 20; i++) pong_draw(dpy, XSHIM_WINDOW, st);
  int tinted = 0, white = 0;
  for (int i = 0; i < cv.w * cv.h; i++) {
    const uint16_t p = px_swap(cv.px[i]);
    const int r = (p >> 11) << 3, g = ((p >> 5) & 0x3F) << 2, b = (p & 0x1F) << 3;
    if (abs(r - g) > 40 || abs(g - b) > 40) tinted++;
    if (p == 0xFFFF) white++;
  }
  TEST_ASSERT_TRUE_MESSAGE(white > 500, "the paddles and ball should be white");
  TEST_ASSERT_TRUE_MESSAGE(tinted < cv.w * cv.h / 50, "the picture should be grey, not tinted");
  pong_free(dpy, XSHIM_WINDOW, st);
}

int main(void) {
  UNITY_BEGIN();
  RUN_TEST(test_the_colour_tables_are_in_canvas_order);
  RUN_TEST(test_a_frame_is_neutral_grey_and_white_not_tinted);
  return UNITY_END();
}

