            "static void analogtv_init_signal"
        )
    ]
    old = _add_signal(source).replace("analogtv_add_signal", "add_old")
    new = _add_signal(ap.float_ghost_filter(source)).replace(
        "analogtv_add_signal", "add_new"
    )
    harness = textwrap.dedent(
        """\
        #include <limits.h>
