              add_old(&it, &rec, start, end, 0);
              add_new(&jt, &rec, start, end, 0);
              for (unsigned i = start; i < end; i++) {
                const double d = fabs((double)a[i] - (double)b[i]);
                const double scale = fmax(1.0, fabs((double)a[i]));
                if (d / scale > worst) worst = d / scale;
                checked++;
              }
            }
